bool LieObserveActivation(const Config& config, const float* values,
                          std::uint32_t tokens, std::uint32_t start,
                          std::uint32_t layer, bool ffn, hipStream_t stream,
                          std::string* error_msg) {
  auto* observer = lie_gufo::activation_observer;
  if (!prefill_phase || observer == nullptr)
    return true;
  const auto component = ffn ? LIE_ACTIVATION_FFN : LIE_ACTIVATION_ATTENTION;
  const auto branches = ffn ? config.hc_count : 1U;
  float* destination = observer->destination(start, tokens, layer, component,
                                             config.hidden_size, branches);
  if (destination == nullptr)
    return true;
  const std::size_t count = static_cast<std::size_t>(config.hidden_size) * branches;
  const std::size_t offset = static_cast<std::size_t>(tokens - 1) * count;
  if (!Check(hipMemcpyAsync(destination, values + offset, count * sizeof(float),
                            hipMemcpyDeviceToHost, stream),
             "activation observation row copy", error_msg) ||
      !Check(hipStreamSynchronize(stream), "activation observation completion", error_msg))
    return false;
  observer->emit(layer, component, branches);
  return true;
}

